    private static Vector3 V3(float[] t, int f) { int i = f * 3; return new Vector3(t[i], t[i + 1], t[i + 2]); }
    private static Vector3 Lerp3(float[] t, int frames, float frame)
    {
        if (frame <= 0f) return V3(t, 0);
        if (frame >= frames - 1) return V3(t, frames - 1);
        int f = (int)frame; float k = frame - f;
        return V3(t, f).Lerp(V3(t, f + 1), k);
    }
    /// <summary>The camera eye / target / up / fov at time t (seconds since the demo start), held on the last frame.</summary>
    public static void Camera(float t, bool inside, out Vector3 eye, out Vector3 target, out Vector3 up, out float fovDeg)
    {
        float frame = t * Fps;
        float[] fv = inside ? CamFovInside : CamFovOutside; int n = inside ? CamFramesInside : CamFramesOutside;
        if (inside) { eye = Lerp3(CamEyeInside, CamFramesInside, frame); target = Lerp3(CamTargetInside, CamFramesInside, frame); up = Lerp3(CamUpInside, CamFramesInside, frame); }
        else { eye = Lerp3(CamEyeOutside, CamFramesOutside, frame); target = Lerp3(CamTargetOutside, CamFramesOutside, frame); up = Lerp3(CamUpOutside, CamFramesOutside, frame); }
        if (up.LengthSquared() < 1e-6f) up = Vector3.Up; else up = up.Normalized();
        int f = Mathf.Clamp((int)frame, 0, n - 1), g = Mathf.Min(f + 1, n - 1);
        fovDeg = Mathf.Lerp(fv[f], fv[g], Mathf.Clamp(frame - f, 0f, 1f));
    }
    /// <summary>pass 116 signature kept for callers that do not roll the camera.</summary>
    public static void Camera(float t, bool inside, out Vector3 eye, out Vector3 target, out float fovDeg)
    {
        Camera(t, inside, out eye, out target, out _, out fovDeg);
    }
    /// <summary>The star's centre, rotation and scale at time t, held on the last frame.</summary>
    public static void Shine(float t, out Vector3 star, out Quaternion rot, out float scale)
    {
        float frame = t * Fps;
        star = Lerp3(ShineStar, ShineFrames, frame);
        int f = Mathf.Clamp((int)frame, 0, ShineFrames - 1), g = Mathf.Min(f + 1, ShineFrames - 1);
        float k = Mathf.Clamp(frame - f, 0f, 1f);
        var qa = new Quaternion(ShineRot[f * 4], ShineRot[f * 4 + 1], ShineRot[f * 4 + 2], ShineRot[f * 4 + 3]);
        var qb = new Quaternion(ShineRot[g * 4], ShineRot[g * 4 + 1], ShineRot[g * 4 + 2], ShineRot[g * 4 + 3]);
        rot = qa.Normalized().Slerp(qb.Normalized(), k).Normalized();   // the table is rounded: Godot's Slerp insists on unit quaternions
        scale = Mathf.Lerp(ShineScale[f], ShineScale[g], k);
    }
    /// <summary>Joint j's (0 root, 1 starglow, 2 body) local TRS at time t -- what the game's anim puts on the joint; held on the last frame.</summary>
    public static void ShineJoint(int j, float t, out Vector3 pos, out Quaternion rot, out Vector3 scale)
    {
        float frame = Mathf.Clamp(t * Fps, 0f, ShineFrames - 1);
        int f = Mathf.Clamp((int)frame, 0, ShineFrames - 1), g = Mathf.Min(f + 1, ShineFrames - 1);
        float k = Mathf.Clamp(frame - f, 0f, 1f);
        int a = j * ShineFrames + f, b = j * ShineFrames + g;
        pos = new Vector3(ShineJointT[a * 3], ShineJointT[a * 3 + 1], ShineJointT[a * 3 + 2]).Lerp(new Vector3(ShineJointT[b * 3], ShineJointT[b * 3 + 1], ShineJointT[b * 3 + 2]), k);
        var qa = new Quaternion(ShineJointQ[a * 4], ShineJointQ[a * 4 + 1], ShineJointQ[a * 4 + 2], ShineJointQ[a * 4 + 3]);
        var qb = new Quaternion(ShineJointQ[b * 4], ShineJointQ[b * 4 + 1], ShineJointQ[b * 4 + 2], ShineJointQ[b * 4 + 3]);
        rot = qa.Normalized().Slerp(qb.Normalized(), k).Normalized();
        scale = new Vector3(ShineJointS[a * 3], ShineJointS[a * 3 + 1], ShineJointS[a * 3 + 2]).Lerp(new Vector3(ShineJointS[b * 3], ShineJointS[b * 3 + 1], ShineJointS[b * 3 + 2]), k);
    }
